function speak(text: string, locale: string) { if (typeof window !== "undefined" && "speechSynthesis" in window) { window.speechSynthesis.cancel(); const utterance = new SpeechSynthesisUtterance(text); utterance.lang = locale; utterance.rate = locale === "zh-TW" ? 0.82 : 0.72; utterance.pitch = 1.12; window.speechSynthesis.speak(utterance); } }
