function normalizeVoiceText(value: string, language: Language) { const text = value.trim().toLowerCase().replace(/[\s，。！？、,.!?]/g, ""); return language === "chinese" ? text.replace(/[的了嗎呢啊]/g, "") : text; }
function getExampleSentence(item: Word) { return { english: `Look at the ${item.word}.`, chinese: `看！這是${item.translation}。` }; }
function getSpeechAccuracy(expected: string, spoken: string, language: Language) { const expectedText = normalizeVoiceText(expected, language); const spokenText = normalizeVoiceText(spoken, language); if (!expectedText || !spokenText) return 0; if (expectedText === spokenText) return 100; if (language === "english") { const expectedWords = expectedText.match(/[a-z]+/g) ?? []; const spokenWords = new Set(spokenText.match(/[a-z]+/g) ?? []); return Math.round((expectedWords.filter((word) => spokenWords.has(word)).length / Math.max(1, expectedWords.length)) * 100); } const expectedCharacters = Array.from(expectedText); const spokenCharacters = new Set(Array.from(spokenText)); return Math.round((expectedCharacters.filter((character) => spokenCharacters.has(character)).length / Math.max(1, expectedCharacters.length)) * 100); }

