  useEffect(() => { const previous = previousProgressPercent.current; previousProgressPercent.current = completedPercent; if (previous !== null) { const milestone = [25, 50, 100].find((value) => previous < value && completedPercent >= value); if (milestone) { setProgressMilestone(milestone); setSummarySnapshot({ correct: sessionCorrectIds.length, skipped: sessionSkippedIds.length, review: sessionReviewIds.length }); if (milestone === 100) { setCompletionSummaryOpen(true); setProgressCelebration(false); } else setProgressCelebration(true); playEffect("celebrate", gameSoundsEnabled); speak(milestone === 100 ? "You grew the whole word garden!" : `You reached ${milestone} percent!`, "en-US"); const timer = window.setTimeout(() => { setProgressCelebration(false); setProgressMilestone(null); }, 5200); return () => window.clearTimeout(timer); } } }, [completedPercent, gameSoundsEnabled, sessionCorrectIds, sessionSkippedIds, sessionReviewIds]); useEffect(() => { const previous = previousGoalPercent.current; previousGoalPercent.current = goalPercent; if (previous === null) return; const crossedGoal = previous < 100 && goalPercent >= 100; if (crossedGoal && !goalCelebrated) { setGoalCelebrated(true); setCelebration(true); playEffect("celebrate", gameSoundsEnabled); speak("You reached your daily goal!", "en-US"); const timer = window.setTimeout(() => setCelebration(false), 5200); return () => window.clearTimeout(timer); } if (goalPercent < 100) setGoalCelebrated(false); }, [goalPercent, goalCelebrated, gameSoundsEnabled]);
